package dev.networkwatch;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.Test;
class AnalysisToolsTest{Analyzer.Event e(long t,long b,String region,boolean ok){return new Analyzer.Event(t,"demo","192.0.2.1",b>0?"traffic":"auth",ok,b,region);}@Test void baselineFindsNewRegionsAndOutliers(){var b=Baseline.from(List.of(e(1,100,"a",true),e(2,100,"a",true)));assertTrue(b.unusualBytes(1000));assertEquals(Set.of("b"),b.newRegions(List.of(e(3,0,"b",true))));}@Test void timelineBucketsEvents(){var x=new Timeline().bucket(List.of(e(1,0,"a",false),e(61,200,"a",true)),60);assertEquals(2,x.size());assertEquals(1,x.getFirst().failedAuth());}@Test void formatterIsRedacted(){var i=new Analyzer().analyze(List.of(e(1,0,"a",true)));var text=new IncidentFormatter().text(i);assertTrue(text.contains("subject-"));assertFalse(text.contains("demo\n"));}}
